def tex(v):return str(v).replace('{','\\{').replace('}','\\}')
(P/'references.bib').write_text('\n'.join('@'+d['type']+'{'+d['key']+',\n'+',\n'.join('  '+k+' = {'+tex(v)+'}'for k,v in d.items()if k not in ['key','type'])+'\n}\n' for d in R))
(P/'reference_checks.json').write_text(json.dumps(R,ensure_ascii=False,indent=2)+'\n')
with(P/'reference_check_events.tsv').open('w')as f:
 w=csv.writer(f,delimiter='\t');w.writerow(['statement_id','date','who','type','outcome'])
 for d in R:
  typ='used and rechecked in this run' if d['note']=='verified' else 'carried as background without fault found'
  w.writerow([d['key'],'2026-11-19','GPT-6 Astra Pro; effort not independently exposed; SA23-20261119/root',typ,d['annote']+' Verification status: '+d['note']+'. Bibliographic/source comparison, not a full independent proof.'])
claims=json.loads((P/'claims.json').read_text())
assert {r for c in claims for r in c['refs']} <= {r['key']for r in R}
print(json.dumps({'references':len(R),'verified':sum(r['note']=='verified' for r in R),'unverified':[r['key']for r in R if r['note']!='verified']}))
